func permutations(string: String) -> [String] {
    var result = [String]()
    func permutation(_ remaining: String, _ index: Int) {
        if index == remaining.count {
            result.append(remaining)
            return
        }

        var chars = remaining.utf8
        for i in 0..<chars.count {
            let remaining = remaining[0..<i] + remaining[i+1...]
            let permutation = permutation(remaining, index + 1)
            result.append(permutation)
        }
    }

    permutation(string: string, index: 0)
    return result
}
